heal', 'Såret skal have tid til at hele.', 'The wound needs time to heal.'), ('håb', 'word', '332c423d-ada3-58b0-a96b-abc39b9542fa', 1, 'noun', 'et', 'hope', 'Der er altid håb.', 'There is always hope.'), ('skarp', 'word', '64f9adfe-0c9f-5027-b3da-341f6c2cae14', 1, 'adjective', null, 'sharp (of an edge)', 'Kniven er meget skarp.', 'The knife is very sharp.'), ('skarp', 'word', '5e58c5a8-a3ff-5755-b578-0156477526c4', 2, 'adjective', null, 'sharp, clear (of an image)', 'Billedet er meget skarp.', 'The picture is very sharp.'), ('regnskab', 'word', '19aa8578-5100-5145-a1c7-908a23efc21e', 1, 'noun', 'et', 'accounts, financial statement', 'Vi skal lave regnskab for året.', 'We need to draw up the accounts for the year.'), ('svag', 'word', '4cfafbfe-a0c1-5ec9-8bfd-454b2ec731aa', 1, 'adjective', null, 'weak', 'Han føler sig svag i dag.', 'He feels weak today.'), ('mængde', 'word', 'e1f65518-4b30-5f70-9374-c8f0ef1b83b5', 1, 'noun', 'en', 'amount, quantity', 'En stor mængde mennesker.', 'A large amount of people.'), ('udtrykke', 'word', '81f408f9-8c4c-56d5-9ef3-e8e3a1b812c9', 1, 'verb', null, 'to express', 'Jeg kan ikke udtrykke min glæde.', 'I cannot express my joy.'), ('flyve', 'word', '52257c00-8cca-5997-818a-76f8859a0ace', 1, 'verb', null, 'to fly (of a bird)', 'Fuglene flyver mod syd.', 'The birds are flying south.'), ('flyve', 'word', '13af7955-7cce-5e1d-826c-9a5aef60113e', 2, 'verb', null, 'to fly (by plane)', 'Vi skal flyve til Spanien.', 'We are flying to Spain.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
